import time

TRANSIENT = {"timeout", "503", "connection reset"}

def call_with_retry(fn, *args, retries=2):
    for attempt in range(retries + 1):
        try:
            return fn(*args)
        except Exception as e:
            msg = str(e).lower()
            transient = any(t in msg for t in TRANSIENT)
            if not transient or attempt == retries:
                raise                    # permanent OR out of tries -> surface it
            time.sleep(2 ** attempt)     # backoff, then retry
# 404s bubble up immediately; timeouts get a few chances

import concurrent.futures as cf

def call_with_timeout(fn, *args, seconds=5) -> dict:
    with cf.ThreadPoolExecutor(max_workers=1) as ex:
        future = ex.submit(fn, *args)
        try:
            return {"ok": True, "data": future.result(timeout=seconds)}
        except cf.TimeoutError:
            # abort and report -- do not let it hang the loop
            return {"ok": False, "error": f"tool timed out after {seconds}s"}

def dispatch(name, args, tools) -> dict:
    fn = tools.get(name)
    if fn is None:
        return {"ok": False, "error": f"unknown tool {name!r}"}
    try:
        return {"ok": True, "data": fn(**args)}
    except TypeError as e:                 # bad/missing arguments
        return {"ok": False, "error": f"bad arguments: {e}"}
    except Exception as e:                  # anything else the tool throws
        return {"ok": False, "error": f"{type(e).__name__}: {e}"}
# the loop never sees a raised exception, so it can never crash here

