import time

TRANSIENT = ("timeout", "503", "429", "connection reset")

def is_transient(err: Exception) -> bool:
    msg = str(err).lower()
    return any(marker in msg for marker in TRANSIENT)

def call_with_retry(fn, retries=3, sleep=time.sleep) -> dict:
    for attempt in range(retries + 1):
        try:
            return {"ok": True, "data": fn(), "error": None}
        except Exception as e:
            # permanent, or out of attempts -> surface it, don't raise
            if not is_transient(e) or attempt == retries:
                return {"ok": False, "data": None, "error": str(e)}
            sleep(2 ** attempt)  # exponential backoff before next try

if __name__ == "__main__":
    tries = {"n": 0}
    def flaky():
        tries["n"] += 1
        if tries["n"] < 3:
            raise TimeoutError("request timeout")
        return "ok"
    print(call_with_retry(flaky, sleep=lambda s: None), tries["n"])
    print(call_with_retry(lambda: (_ for _ in ()).throw(LookupError("404"))))
